function Emblem({ small = false }: { small?: boolean }) {
  return <span className={cn("grid shrink-0 place-items-center border border-primary/25 bg-primary/10 text-primary", small ? "size-8" : "size-10")} aria-hidden="true"><ShieldCheck size={small ? 17 : 21} strokeWidth={1.7} /></span>;
}

function Brand({ inverse = false, small = false }: { inverse?: boolean; small?: boolean }) {
  return <span className="flex items-center gap-3"><Emblem small={small} /><span className="min-w-0"><span className={cn("block font-semibold tracking-[0.08em]", inverse ? "text-primary-foreground" : "text-foreground")}>CV-TRUST</span><span className={cn("block truncate text-[10px]", inverse ? "text-primary-foreground/60" : "text-muted-foreground")}>Computer Vision Integrity Assurance</span></span></span>;
}

function Status({ children, tone = "neutral" }: { children: ReactNode; tone?: "good" | "watch" | "risk" | "neutral" }) {
  const styles = { good: "status-good", watch: "status-watch", risk: "status-risk", neutral: "status-neutral" };
  return <Badge variant="outline" className={cn("rounded-sm px-2 py-1 text-[10px] font-semibold tracking-[0.06em]", styles[tone])}>{children}</Badge>;
}

function PageHeading({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: ReactNode }) {
  return <div className="mb-7 grid grid-cols-[minmax(0,1fr)_auto] items-end gap-4 border-b border-border pb-5"><div className="min-w-0"><p className="mb-2 text-[10px] font-semibold uppercase tracking-[0.14em] text-primary">{eyebrow ?? "Assurance workspace"}</p><h1 className="truncate text-2xl font-semibold tracking-tight text-foreground">{title}</h1>{description && <p className="mt-2 max-w-3xl text-sm leading-6 text-muted-foreground">{description}</p>}</div>{action && <div className="shrink-0">{action}</div>}</div>;
}

function SectionTitle({ title, note, action }: { title: string; note?: string; action?: ReactNode }) {
  return <div className="mb-4 flex min-w-0 items-end justify-between gap-3"><div className="min-w-0"><h2 className="text-sm font-semibold text-foreground">{title}</h2>{note && <p className="mt-1 text-xs text-muted-foreground">{note}</p>}</div>{action}</div>;
}

function Surface({ children, className }: { children: ReactNode; className?: string }) {
  return <section className={cn("border border-border bg-card", className)}>{children}</section>;
}

function Metric({ label, value, meta, icon: Icon, tone = "plain" }: { label: string; value: string; meta: string; icon: typeof Activity; tone?: "plain" | "watch" | "good" }) {
  return <Surface className="p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-[11px] font-medium text-muted-foreground">{label}</p><p className="mt-2 text-3xl font-semibold tabular-nums text-foreground">{value}</p><p className={cn("mt-2 text-[11px]", tone === "watch" ? "text-status-watch" : tone === "good" ? "text-status-good" : "text-muted-foreground")}>{meta}</p></div><span className="grid size-9 place-items-center border border-border bg-muted text-primary"><Icon size={17} strokeWidth={1.7} /></span></div></Surface>;
}

